<?php
session_start(); require_once __DIR__.'/includes/config.php';
if(empty($_SESSION['alogin'])||empty($_SESSION['uid'])){header('Location: index.php');exit;}
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$error=''; $categorias=$dbh->query("SELECT id,nombre FROM categorias_activos WHERE estado='ACTIVA' ORDER BY nombre")->fetchAll();
$sedes=$dbh->query("SELECT id,nombre FROM sedes WHERE estado='ACTIVA' ORDER BY nombre")->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){
 $ids=array_values(array_unique(array_filter(array_map('intval',$_POST['activos']??[]))));
 $tipo=$_POST['tipo_mantenimiento']??''; $fecha=$_POST['fecha_programada']??''; $actividad=trim($_POST['actividad']??''); $tecnico=trim($_POST['tecnico']??''); $obs=trim($_POST['observaciones']??''); $modoProxima=$_POST['modo_proxima']??'intervalo'; $meses=(int)($_POST['periodicidad_meses']??0); $fechaManual=$_POST['proxima_fecha_manual']??'';
 if($modoProxima==='intervalo' && !in_array($meses,[3,6,12],true)) $meses=6; if($modoProxima==='manual' && !$fechaManual) $error='Indique la próxima fecha de mantenimiento.';
 if(!$error && (!$ids||!in_array($tipo,['PREVENTIVO','CORRECTIVO','REPARACION'],true)||!$fecha||!$actividad)){$error='Seleccione al menos un activo y complete tipo, fecha y actividad.';}
 else { try{$dbh->beginTransaction();
  $ph=implode(',',array_fill(0,count($ids),'?'));
  $q=$dbh->prepare("SELECT id FROM activos WHERE id IN ($ph) AND estado<>'DADO_DE_BAJA_OBSOLETO'");$q->execute($ids);$validos=array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));
  if(count($validos)!==count($ids)) throw new Exception('Uno o más activos no existen o están dados de baja. Actualice la selección.');
  $nombre='Jornada '.$tipo.' - '.$fecha;
  $j=$dbh->prepare("INSERT INTO jornadas_mantenimiento(nombre,tipo_mantenimiento,fecha_programada,actividad,tecnico_responsable,periodicidad_meses,proxima_fecha_manual,observaciones,registrado_por) VALUES(?,?,?,?,?,?,?,?,?)");$j->execute([$nombre,$tipo,$fecha,$actividad,$tecnico?:null,$modoProxima==='intervalo'?$meses:null,$modoProxima==='manual'?$fechaManual:null,$obs?:null,(int)$_SESSION['uid']]);$jid=(int)$dbh->lastInsertId();
  $m=$dbh->prepare("INSERT INTO mantenimientos(activo_id,tipo_mantenimiento,fecha_programada,diagnostico,tecnico_responsable,observaciones,resultado,registrado_por,jornada_id,estado_atencion) VALUES(?,?,?,?,?,?,'PENDIENTE',?,?, 'PENDIENTE')");
  foreach($validos as $aid)$m->execute([$aid,$tipo,$fecha,$actividad,$tecnico?:null,$obs?:null,(int)$_SESSION['uid'],$jid]);
  $a=$dbh->prepare("INSERT INTO auditoria(usuario_id,tabla_afectada,registro_id,accion,descripcion,direccion_ip) VALUES(?, 'jornadas_mantenimiento', ?, 'INSERT', ?, ?)");$a->execute([(int)$_SESSION['uid'],$jid,'Programación masiva '.$tipo.'; activos: '.count($validos).'; fecha: '.$fecha,$_SERVER['REMOTE_ADDR']??null]);
  $dbh->commit();header('Location: ejecutar-jornada.php?id='.$jid.'&creada=1');exit;
 }catch(Throwable $e){if($dbh->inTransaction())$dbh->rollBack();$error=$e->getMessage();}}
}
$cat=(int)($_GET['categoria']??0);$sede=(int)($_GET['sede']??0);$area=trim($_GET['area']??'');
$sqlA="SELECT a.id,a.codigo_inventario,a.descripcion,a.marca,a.modelo,c.nombre categoria,s.nombre sede,u.nombre ubicacion,u.area_departamento area FROM activos a JOIN categorias_activos c ON c.id=a.categoria_id LEFT JOIN ubicaciones u ON u.id=a.ubicacion_id LEFT JOIN sedes s ON s.id=u.sede_id WHERE a.estado<>'DADO_DE_BAJA_OBSOLETO'";$p=[];
if($cat){$sqlA.=' AND a.categoria_id=?';$p[]=$cat;} if($sede){$sqlA.=' AND u.sede_id=?';$p[]=$sede;} if($area!==''){$sqlA.=' AND (u.area_departamento LIKE ? OR u.nombre LIKE ?)';$p[]='%'.$area.'%';$p[]='%'.$area.'%';}
$sqlA.=' ORDER BY s.nombre,u.area_departamento,a.codigo_inventario';$st=$dbh->prepare($sqlA);$st->execute($p);$activos=$st->fetchAll();
include __DIR__.'/includes/topbar.php'; ?>
