<div class="row"><div class="form-group col-md-4"><label>Tipo de mantenimiento *</label><select name="tipo_mantenimiento" class="form-control" required><option value="">Seleccione</option><option value="PREVENTIVO">Preventivo</option><option value="CORRECTIVO">Correctivo</option><option value="REPARACION">Reparación</option></select></div><div class="form-group col-md-4"><label>Fecha programada *</label><input type="date" name="fecha_programada" min="<?=date('Y-m-d')?>" class="form-control" required></div><div class="form-group col-md-4"><label>Próximo mantenimiento</label><select name="modo_proxima" id="modoProxima" class="form-control"><option value="intervalo">Por periodicidad</option><option value="manual">Fecha manual</option></select></div><div class="form-group col-md-4" id="periodoBox"><label>Periodicidad</label><select name="periodicidad_meses" class="form-control"><option value="3">Cada 3 meses</option><option value="6" selected>Cada 6 meses</option><option value="12">Cada 12 meses</option></select></div><div class="form-group col-md-4" id="fechaManualBox" style="display:none"><label>Próxima fecha</label><input type="date" name="proxima_fecha_manual" class="form-control"></div><div class="form-group col-md-4"><label>Técnico / responsable</label><input name="tecnico" maxlength="150" class="form-control" placeholder="Texto libre"></div><div class="form-group col-md-12"><label>Actividad *</label><textarea name="actividad" class="form-control" rows="3" required></textarea></div><div class="form-group col-md-12"><label>Observaciones</label><textarea name="observaciones" class="form-control" rows="2"></textarea></div><div class="col-md-12"><button class="btn btn-primary">Crear jornada y programar seleccionados</button> <a href="manage-mantenimientos.php" class="btn btn-default">Cancelar</a></div></div></form>
</div></div></div></section></div></div></div><script>document.getElementById('todos').addEventListener('change',function(){document.querySelectorAll('.activo-check').forEach(x=>x.checked=this.checked);});document.getElementById('modoProxima').addEventListener('change',function(){document.getElementById('periodoBox').style.display=this.value==='intervalo'?'':'none';document.getElementById('fechaManualBox').style.display=this.value==='manual'?'':'none';});</script><?php include __DIR__.'/includes/footer.php'; ?>